@Override
public void fillAndStrokePath(int windingRule) throws IOException {
    // Cloning needed because fillPath() resets linePath
    GeneralPath path = ((GeneralPath) (linePath.clone()));
    fillPath(windingRule);
    linePath = path;
    strokePath();
