@Override
public void fillPath(int windingRule) throws IOException {
    PDGraphicsState graphicsState = getGraphicsState();
    graphics.setComposite(graphicsState.getNonStrokingJavaComposite());
    setClip();
    linePath.setWindingRule(windingRule);
