/**
 * Creates a buffered image for a transparency group result.
 *
 * @param form
 * 		the transparency group of the form or soft mask.
 * @param isSoftMask
 * 		true if this is a soft mask.
 * @param ctm
 * 		the relevant current transformation matrix. For soft masks, this is the CTM at
 * 		the time the soft mask is set (not at the time the soft mask is used for fill/stroke!),
 * 		for forms, this is the CTM at the time the form is invoked.
 * @param backdropColor
 * 		the color according to the /bc entry to be used for luminosity soft
 * 		masks.
 * @throws IOException
 */
private (PDTransparencyGroup form, boolean isSoftMask, Matrix ctm, PDColor backdropColor) throws IOException {
    Graphics2D savedGraphics = graphics;
    List<Path2D> savedLastClips = lastClips;
    Shape savedInitialClip = initialClip;
    // get the CTM x Form Matrix transform
    Matrix transform = Matrix.concatenate(ctm, form.getMatrix());
