 */
protected final Paint getNonStrokingPaint() throws IOException {
    PDGraphicsState graphicsState = getGraphicsState();
    // PATH: Test should invoke the next PageDrawer.applySoftMaskToPaint(...) [step in execution path]
    return applySoftMaskToPaint(getPaint(graphicsState.getNonStrokingColor()), graphicsState.getSoftMask());
