    }
    Graphics2D g = image.createGraphics();
    if (needsBackdrop) {
        // backdropImage must be included in group image but not in group alpha.
        g.drawImage(backdropImage, 0, 0, width, height, backdropX, backdropY, backdropX + width, backdropY + height, null);
