 * @param colorSpace
 * 		color space for this tiling.
 * @param color
 * 		color for this tiling.
 * @param patternMatrix
 * 		the pattern matrix
 * @throws IOException
 * 		If there is an IO error while drawing the page.
 */
void drawTilingPattern(Graphics2D g, PDTilingPattern pattern, PDColorSpace colorSpace, PDColor color, Matrix patternMatrix) throws IOException {
    Graphics2D savedGraphics = graphics;
    graphics = g;
    GeneralPath savedLinePath = linePath;
    linePath = new GeneralPath();
    int savedClipWindingRule = clipWindingRule;
    clipWindingRule = -1;
    List<Path2D> savedLastClips = lastClips;
    lastClips = null;
    Shape savedInitialClip = initialClip;
    initialClip = null;
    boolean savedFlipTG = flipTG;
    flipTG = true;
    setRenderingHints();
    processTilingPattern(pattern, color, colorSpace, patternMatrix);
    flipTG = savedFlipTG;
    graphics = savedGraphics;
    linePath = savedLinePath;
    lastClips = savedLastClips;
    initialClip = savedInitialClip;
    clipWindingRule = savedClipWindingRule;
}

