@Override
public void shadingFill(COSName shadingName) throws IOException {
    if (!isContentRendered()) {
        return;
    }
    PDShading shading = getResources().getShading(shadingName);
    if (shading == null) {
        LOG.error(("shading " + shadingName) + " does not exist in resources dictionary");
        return;
    }
    Matrix ctm = getGraphicsState().getCurrentTransformationMatrix();
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    Shape savedClip = graphics.getClip();
    graphics.setClip(null);
    lastClips = null;
    // get the transformed BBox and intersect with current clipping path
    // need to do it here and not in shading getRaster() because it may have been rotated
    PDRectangle bbox = shading.getBBox();
    Area area;
    if (bbox != null) {
        area = new Area(bbox.transform(ctm));
        area.intersect(getGraphicsState().getCurrentClippingPath());
    } else {
        Rectangle2D bounds = shading.getBounds(new AffineTransform(), ctm);
        if (bounds != null) {
            bounds.add(new Point2D.Double(Math.floor(bounds.getMinX() - 1), Math.floor(bounds.getMinY() - 1)));
            bounds.add(new Point2D.Double(Math.ceil(bounds.getMaxX() + 1), Math.ceil(bounds.getMaxY() + 1)));
            area = new Area(bounds);
            area.intersect(getGraphicsState().getCurrentClippingPath());
        } else {
            area = getGraphicsState().getCurrentClippingPath();
        }
    }
    if (!area.isEmpty()) {
        // creating Paint is sometimes a costly operation, so avoid if possible
        Paint paint = shading.toPaint(ctm);
        paint = applySoftMaskToPaint(paint, getGraphicsState().getSoftMask());
        graphics.setPaint(paint);
        graphics.fill(area);
    }
    graphics.setClip(savedClip);
}

@Override
public void showAnnotation(PDAnnotation annotation) throws IOException {
    lastClips = null;
    if (shouldSkipAnnotation(annotation)) {
        return;
    }
    // TODO support NoZoom, example can be found in p5 of PDFBOX-2348
    PDAppearanceDictionary appearance = annotation.getAppearance();
    if ((appearance == null) || (appearance.getNormalAppearance() == null)) {
        annotation.constructAppearances(renderer.document);
    }
    if (annotation.isNoRotate() && (getCurrentPage().getRotation() != 0)) {
        appearance = annotation.getAppearance();
        if (appearance != null) {
            PDAppearanceEntry appearanceEntry = appearance.getNormalAppearance();
            if (((appearanceEntry != null) && appearanceEntry.isStream()) && hasTransparency(appearanceEntry.getAppearanceStream())) {
                // PDFBOX-4744: avoid appearances with transparency groups until we have fixed
                // the rendering. A real solution should probably be
                // in PDFStreamEngine.processAnnotation().
                annotation.constructAppearances();
            }
        }
        PDRectangle rect = annotation.getRectangle();
        AffineTransform savedTransform = graphics.getTransform();
        // "The upper-left corner of the annotation remains at the same point in
        // default user space; the annotation pivots around that point."
        graphics.rotate(Math.toRadians(getCurrentPage().getRotation()), rect.getLowerLeftX(), rect.getUpperRightY());
        super.showAnnotation(annotation);
        graphics.setTransform(savedTransform);
        annotation.setAppearance(appearance);// restore

    } else {
        super.showAnnotation(annotation);
    }
}

@Override
protected void showFontGlyph(Matrix textRenderingMatrix, PDFont font, int code, Vector displacement) throws IOException {
    AffineTransform at = textRenderingMatrix.createAffineTransform();
    at.concatenate(font.getFontMatrix().createAffineTransform());
    // create cache if it does not exist
    PDVectorFont vectorFont = ((PDVectorFont) (font));
    GlyphCache cache = glyphCaches.get(font);
    if (cache == null) {
        cache = new GlyphCache(vectorFont);
        glyphCaches.put(font, cache);
    }
    GeneralPath path = cache.getPathForCharacterCode(code);
    drawGlyph(path, font, code, displacement, at);
}

/**
 * {@inheritDoc }
 */
@Override
public void showForm(PDFormXObject form) throws IOException {
    if (isHiddenOCG(form.getOptionalContent())) {
        return;
    }
    if (isContentRendered()) {
        GeneralPath savedLinePath = linePath;
        linePath = new GeneralPath();
        super.showForm(form);
        linePath = savedLinePath;
    }
}

/**
 * For advanced users, to extract the transparency group into a separate graphics device.
 *
 * @param form
 * 		the transparency group to be extracted
 * @param graphics
 * 		the target graphics device
 * @throws IOException
 * 		if the transparency group could not be extracted
 */
protected void showTransparencyGroupOnGraphics(PDTransparencyGroup form, Graphics2D graphics) throws IOException {
    if (isHiddenOCG(form.getOptionalContent())) {
        return;
    }
    if (!isContentRendered()) {
        return;
    }
    TransparencyGroup group = new TransparencyGroup(form, false, getGraphicsState().getCurrentTransformationMatrix(), null);
    BufferedImage image = group.getImage();
    if (image == null) {
        // image is empty, don't bother
        return;
    }
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    setClip();
    // both the DPI xform and the CTM were already applied to the group, so all we do
    // here is draw it directly onto the Graphics2D device at the appropriate position
    AffineTransform savedTransform = graphics.getTransform();
    AffineTransform transform = new AffineTransform(xform);
    transform.scale(1.0 / xformScalingFactorX, 1.0 / xformScalingFactorY);
    graphics.setTransform(transform);
    // adjust bbox (x,y) position at the initial scale + cropbox
    PDRectangle bbox = group.getBBox();
    float x = bbox.getLowerLeftX() - pageSize.getLowerLeftX();
    float y = pageSize.getUpperRightY() - bbox.getUpperRightY();
    if (flipTG) {
        graphics.translate(0, image.getHeight());
        graphics.scale(1, -1);
    } else {
        graphics.translate(x * xformScalingFactorX, y * xformScalingFactorY);
    }
    PDSoftMask softMask = getGraphicsState().getSoftMask();
    if (softMask != null) {
        Paint awtPaint = new TexturePaint(image, new Rectangle2D.Float(0, 0, image.getWidth(), image.getHeight()));
        awtPaint = applySoftMaskToPaint(awtPaint, softMask);
        graphics.setPaint(awtPaint);
        graphics.fill(new Rectangle2D.Float(0, 0, bbox.getWidth() * xformScalingFactorX, bbox.getHeight() * xformScalingFactorY));
    } else {
        try {
            graphics.drawImage(image, null, null);
        } catch (InternalError ie) {
            LOG.error("Exception drawing image, see JDK-6689349, " + "try rendering into a BufferedImage instead", ie);
        }
    }
    graphics.setTransform(savedTransform);
}

@Override
public void strokePath() throws IOException {
    if (isContentRendered()) {
        graphics.setComposite(getGraphicsState().getStrokingJavaComposite());
        graphics.setPaint(getStrokingPaint());
        graphics.setStroke(getStroke());
        setClip();
        graphics.draw(linePath);
    }
    linePath.reset();
}

